bool HasTwoSum(const std::vector<int>& A, int t) {
  std::size_t left = 0, end = A.size();
  while (left < end) {
    std::int64_t actual = static_cast<std::int64_t>(A[left]) + A[end - 1];
    if (actual == static_cast<std::int64_t>(t))
      return true;
    if (actual < t)
      ++left;
    else
      --end;
  }
  return false;
}

