struct HashTuple;

bool IsPatternSuffixContainedStartingAtXY(const vector<vector<int>>&, int, int, const vector<int>&,
                                          int, unordered_set<tuple<int, int, int>, HashTuple>*);

struct HashTuple {
  size_t operator()(const tuple<int, int, int>& t) const {
    return hash<int>()(get<0>(t) ^ get<1>(t) * 1021 ^ get<2>(t) * 1048573);
  }
};

bool IsPatternContainedInGrid(const vector<vector<int>>& grid, const vector<int>& pattern) {
  if (pattern.empty())
    return true;

  for (int i = 0; i < size(grid); ++i) {
    for (int j = 0; j < size(grid[i]); ++j) {
      if (IsPatternSuffixContainedStartingAtXY(
              grid, i, j, pattern, /*offset=*/0,
              make_unique<unordered_set<tuple<int, int, int>, HashTuple>>().get())) {
        return true;
      }
    }
  }
  return false;
}

bool IsPatternSuffixContainedStartingAtXY(
    const vector<vector<int>>& grid, int x, int y, const vector<int>& pattern, int offset,
    unordered_set<tuple<int, int, int>, HashTuple>* previous_attempts) {
  if (size(pattern) == offset) {
    // Nothing left to complete.
    return true;
  }
  // Early return if (x, y) lies outside the grid or the character does not
  // match or we have already tried this combination.
  if (x < 0 || x >= size(grid) || y < 0 || y >= size(grid[x]) ||
      previous_attempts->find(make_tuple(x, y, offset)) != cend(*previous_attempts) ||
      grid[x][y] != pattern[offset]) {
    return false;
  }

  for (const auto& [next_x, next_y] :
       vector<pair<int, int>>{{x - 1, y}, {x + 1, y}, {x, y - 1}, {x, y + 1}}) {
    if (IsPatternSuffixContainedStartingAtXY(grid, next_x, next_y, pattern, offset + 1,
                                             previous_attempts)) {
      return true;
    }
  }
  previous_attempts->emplace(x, y, offset);
  return false;
}

