int MaximumRevenue(const vector<int>& coins) {
  vector<vector<int>> maximum_revenue_for_range(size(coins), vector<int>(size(coins), 0));
  return ComputeMaximumRevenueForRange(
      coins, 0, size(coins) - 1,
      make_unique<vector<vector<int>>>(size(coins), vector<int>(size(coins), 0)).get());
}

int ComputeMaximumRevenueForRange(const vector<int>& coins, int a, int b,
                                  vector<vector<int>>* maximum_revenue_for_range_ptr) {
  if (a > b) {
    // No coins left.
    return 0;
  }

  vector<vector<int>>& maximum_revenue_for_range = *maximum_revenue_for_range_ptr;
  if (maximum_revenue_for_range[a][b] == 0) {
    int max_revenue_a =
        coins[a] +
        min(ComputeMaximumRevenueForRange(coins, a + 2, b, maximum_revenue_for_range_ptr),
            ComputeMaximumRevenueForRange(coins, a + 1, b - 1, maximum_revenue_for_range_ptr));
    int max_revenue_b =
        coins[b] +
        min(ComputeMaximumRevenueForRange(coins, a + 1, b - 1, maximum_revenue_for_range_ptr),
            ComputeMaximumRevenueForRange(coins, a, b - 2, maximum_revenue_for_range_ptr));
    maximum_revenue_for_range[a][b] = max(max_revenue_a, max_revenue_b);
  }
  return maximum_revenue_for_range[a][b];
}

