public static List<Coordinate> searchMaze(List<List<Color>> maze, Coordinate s, Coordinate e) {
  List<Coordinate> path = new ArrayList<>();
  searchMazeHelper(maze, s, e, path);
  return path;
}

private static boolean searchMazeHelper(
    List<List<Color>> maze, Coordinate cur, Coordinate e, List<Coordinate> path) {
  // Checks cur is within maze and is a white pixel.
  if (cur.x < 0 || cur.x >= maze.size() || cur.y < 0 || cur.y >= maze.get(cur.x).size()
      || maze.get(cur.x).get(cur.y) != Color.WHITE) {
    return false;
  }
  path.add(cur);
  maze.get(cur.x).set(cur.y, Color.BLACK);
  if (cur.equals(e)) {
    return true;
  }

  for (Coordinate nextMove :
      List.of(new Coordinate(cur.x, cur.y + 1), new Coordinate(cur.x, cur.y - 1),
          new Coordinate(cur.x + 1, cur.y), new Coordinate(cur.x - 1, cur.y))) {
    if (searchMazeHelper(maze, nextMove, e, path)) {
      return true;
    }
  }
  // Cannot find a path, remove the entry added in path.add(cur).
  path.remove(path.size() - 1);
  return false;
}

