public static int longestContainedRange(List<Integer> values) {
  var remaining = new HashSet<>(values);
  int best = 0;
  for (int value : values) {
    if (!remaining.remove(value))
      continue;
    int length = 1;
    for (long next = (long) value - 1; next >= Integer.MIN_VALUE && remaining.remove((int) next);
        next--)
      length++;
    for (long next = (long) value + 1; next <= Integer.MAX_VALUE && remaining.remove((int) next);
        next++)
      length++;
    best = Math.max(best, length);
  }
  return best;
}

