private static ListNode<Integer> reverse(ListNode<Integer> head) {
  ListNode<Integer> previous = null;
  while (head != null) {
    var next = head.next;
    head.next = previous;
    previous = head;
    head = next;
  }
  return previous;
}

public static ListNode<Integer> zippingLinkedList(ListNode<Integer> head) {
  if (head == null || head.next == null)
    return head;
  var middle = head;
  var fast = head.next;
  while (fast != null && fast.next != null) {
    middle = middle.next;
    fast = fast.next.next;
  }
  var back = reverse(middle.next);
  middle.next = null;
  var front = head;
  while (back != null) {
    var nextFront = front.next;
    var nextBack = back.next;
    front.next = back;
    back.next = nextFront;
    front = nextFront;
    back = nextBack;
  }
  return head;
}

