std::vector<TrafficSample> CalculateTrafficVolumes(const std::vector<TrafficSample>& samples,
                                                   int width) {
  std::deque<int> candidates;
  std::vector<TrafficSample> result;
  for (int index = 0; index < static_cast<int>(samples.size()); ++index) {
    while (!candidates.empty() &&
           static_cast<long long>(samples[index].time) - samples[candidates.front()].time > width)
      candidates.pop_front();
    while (!candidates.empty() && samples[candidates.back()].volume <= samples[index].volume)
      candidates.pop_back();
    candidates.push_back(index);
    result.push_back({samples[index].time, samples[candidates.front()].volume});
  }
  return result;
}

