public static List<TrafficElement> computeTrafficVolumes(List<TrafficElement> readings, int width) {
  var candidates = new ArrayDeque<Integer>();
  var result = new ArrayList<TrafficElement>();
  for (int current = 0; current < readings.size(); current++) {
    while (!candidates.isEmpty()
        && (long) readings.get(candidates.getFirst()).time
            < (long) readings.get(current).time - width)
      candidates.removeFirst();
    while (!candidates.isEmpty()
        && readings.get(candidates.getLast()).volume <= readings.get(current).volume)
      candidates.removeLast();
    candidates.addLast(current);
    result.add(
        new TrafficElement(readings.get(current).time, readings.get(candidates.getFirst()).volume));
  }
  return result;
}

