public static int findKthLargestUnknownLength(Iterator<Integer> stream, int k) {
  PriorityQueue<Integer> largest = new PriorityQueue<>();
  while (stream.hasNext()) {
    int value = stream.next();
    if (largest.size() < k)
      largest.add(value);
    else if (value > largest.peek()) {
      largest.remove();
      largest.add(value);
    }
  }
  if (largest.size() < k)
    throw new IllegalArgumentException("The stream must contain at least k entries.");
  return largest.element();
}

