Rect IntersectRectangle(const Rect& first, const Rect& second) {
  int left = std::max(first.x, second.x);
  int bottom = std::max(first.y, second.y);
  std::int64_t right = std::min(static_cast<std::int64_t>(first.x) + first.width,
                                static_cast<std::int64_t>(second.x) + second.width);
  std::int64_t top = std::min(static_cast<std::int64_t>(first.y) + first.height,
                              static_cast<std::int64_t>(second.y) + second.height);
  if (left > right || bottom > top)
    return {0, 0, -1, -1};
  return {left, bottom, static_cast<int>(right - left), static_cast<int>(top - bottom)};
}

