    int mid = left + ((right - left) / 2);
    if (A.get(mid) > k) {
      right = mid - 1;
    } else if (A.get(mid) == k) {
      result = mid;
      // Nothing to the right of mid can be the first occurrence of k.
      right = mid - 1;
    } else { // A.get(mid) < k
      left = mid + 1;
    }
  }
  return result;
}

