double SquareRoot(double x) {
  if (x == 0)
    return 0;
  double low = 0, high = std::max(1.0, x);
  for (int step = 0; step < 1100; ++step) {
    double middle = low + (high - low) / 2;
    if (middle == low || middle == high)
      break;
    if (middle <= x / middle)
      low = middle;
    else
      high = middle;
  }
  return low + (high - low) / 2;
}

