class QueueWithMax {
  std::deque<int> values, maxima;

 public:
  void Enqueue(int value) {
    values.push_back(value);
    while (!maxima.empty() && maxima.back() < value)
      maxima.pop_back();
    maxima.push_back(value);
  }
  int Dequeue() {
    if (values.empty())
      throw std::runtime_error("Empty queue");
    int value = values.front();
    values.pop_front();
    if (maxima.front() == value)
      maxima.pop_front();
    return value;
  }
  int Max() const {
    if (values.empty())
      throw std::runtime_error("Empty queue");
    return maxima.front();
  }
};

