}

string Encoding(const string& s) {
  string result;
  for (int i = 1, count = 1; i <= size(s); ++i) {
    if (i == size(s) || s[i] != s[i - 1]) {
      // Found new character so write the count of previous character.
      result += to_string(count) + s[i - 1];
      count = 1;
    } else {  // s[i] == s[i - 1].
      ++count;
    }
  }
  return result;
}

