    if (i == s.length() || s.charAt(i) != s.charAt(i - 1)) {
      // Found new character so write the count of previous character.
      ss.append(count).append(s.charAt(i - 1));
      count = 1;
    } else { // s.charAt(i) == s.charAt(i - 1).
      ++count;
    }
  }
  return ss.toString();
}

